      "type": "object",
      "required": [
        "id",
        "action"
      ],
      "properties": {
        "id": {
          "type": "string",
          "pattern": "^[A-Za-z][A-Za-z0-9._:-]*$"
        },
        "name": {
          "type": "string"
        },
        "action": {
          "$ref": "#/$defs/contractRequirement"
        },
        "provider": {
          "$ref": "#/$defs/providerSelector"
        },
        "requires": {
          "$ref": "#/$defs/requires"
        },
        "if": {
          "type": "object",
          "required": [
            "$expr"
          ],
          "properties": {
            "$expr": {
              "type": "string",
              "minLength": 1
            }
          },
          "additionalProperties": false
        },
        "input": {
          "type": "object",
          "additionalProperties": {}
        },
        "for_each": {
          "type": "object",
          "required": [
            "items"
          ],
          "properties": {
            "items": {},
            "as": {
              "type": "string",
              "pattern": "^[A-Za-z_][A-Za-z0-9_]*$"
            }
          },
          "patternProperties": {
            "^x-[A-Za-z0-9._:-]+$": true
          },
          "additionalProperties": false
        }
      },
      "patternProperties": {
        "^x-[A-Za-z0-9._:-]+$": true
      },
      "additionalProperties": false
    },
    "duration": {
      "type": "string",
      "pattern": "^(0|[1-9][0-9]*)(ms|s|m|h|d)$"
    },
    "runPolicy": {
      "type": "object",
      "required": [],
      "properties": {
        "idempotency": {
          "type": "object",
          "required": [
            "key"
          ],
          "properties": {
            "key": {}
          },
          "patternProperties": {
            "^x-[A-Za-z0-9._:-]+$": true
          },
          "additionalProperties": false
        },
        "concurrency": {
          "type": "object",
          "required": [
            "policy"
          ],
          "properties": {
            "group": {},
            "policy": {
              "enum": [
                "skip",
                "queue",
                "replace",
                "allow"
              ]
            }
          },
          "patternProperties": {
            "^x-[A-Za-z0-9._:-]+$": true
          },
          "additionalProperties": false
        },
        "limits": {
          "type": "object",
          "required": [],
          "properties": {
            "timeout": {
              "$ref": "#/$defs/duration"
            },
            "max_items": {
              "type": "integer",
              "minimum": 1
            }
          },
          "patternProperties": {
            "^x-[A-Za-z0-9._:-]+$": true
          },
          "additionalProperties": false
        },
        "on_error": {
          "enum": [
            "stop",
            "continue"
          ]
        }
      },
      "patternProperties": {
        "^x-[A-Za-z0-9._:-]+$": true
      },
      "additionalProperties": false
